toad_implementation.code_blueprint:
canvas {
  size: 700px 960px;
  fill: #FAF7F0;
  font-family: "EB Garamond, serif";
}

>buetten = #FAF7F0;
>ink = #1A1412;
>rubricRed = #9E2A2B;
>gold = #C2A366;

text #runningHeader {
  at: top center of canvas offset 0px 48px;
  content: "LIBER PRIMUS • DE NATURA RERUM";
  font-size: 11px;
  font-weight: 500;
  color: >gold;
}

rect #headerRule {
  at: below #runningHeader offset 12px;
  size: 540px 1px;
  fill: >gold;
}

text #chapterNumber {
  at: below #headerRule offset 48px;
  content: "CAPITULUM I";
  font-size: 14px;
  font-weight: 700;
  color: >rubricRed;
}

rect #dropCapBox {
  at: below #chapterNumber offset 24px;
  size: 56px 56px;
  fill: >rubricRed;
}

text #dropCapLetter {
  at: center of #dropCapBox;
  content: "I";
  font-size: 42px;
  font-weight: 700;
  color: #FAF7F0;
}

text #firstLineLead {
  at: right of #dropCapBox offset 16px;
  content: "N PRINCIPIO erat Verbum, et";
  font-size: 18px;
  font-weight: 700;
  color: >ink;
}

text #bodyText {
  at: below #dropCapBox offset 16px;
  size: 540px;
  content: "Verbum erat apud Deum, et Deus erat Verbum. Hoc erat in principio apud Deum. Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est. In ipso vita erat, et vita erat lux hominum.";
  font-size: 16px;
  color: >ink;
}

text #pageNumber {
  at: bottom center of canvas offset 0px -40px;
  content: "—  42  —";
  font-size: 12px;
  color: >ink;
}
